{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "신고 목록 조회 쿼리에서 확인한 병목을 근거로 인덱스 추가와 조인 정리를 개선안으로 선택한 판단을 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리에 3.2초가 걸리던 상황이다.",
          "task": "조회 지연의 원인에 맞는 쿼리 개선안을 선택해야 했다.",
          "action": "실행 계획에서 확인한 조회 조건과 테이블 접근 양상을 근거로 인덱스 추가와 조인 정리를 선택한 판단을 설명한다.",
          "result": "개선 후 조회 시간이 0.4초로 단축된 사실은 판단의 맥락을 이해하는 참고 정보로 활용한다."
        },
        "expectedEvidence": [
          "인덱스 추가와 조인 정리를 신고 목록 조회 쿼리의 개선안으로 선택한 판단 근거",
          "실행 계획이나 조회 구조에서 확인한 병목의 구체적인 양상",
          "확인한 병목과 선택한 인덱스 또는 조인 변경 사이의 연결"
        ]
      },
      "question": "포켓마켓의 신고 목록 조회 쿼리 개선에서, 인덱스 추가와 조인 정리를 개선안으로 선택하기로 결정한 판단 근거는 무엇이었나요?",
      "answerTip": "당시 경험을 떠올리며 본인이 했던 일을 중심으로 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "신고 목록 조회 쿼리의 실제 조회 조건, 실행 계획 또는 조인 구조를 짚어 인덱스 추가와 조인 정리를 선택한 근거를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "신고 목록 조회 쿼리에 인덱스를 추가하거나 조인을 정리하면 조회가 빨라진다는 일반적인 근거를 제시하지만, 당시 확인한 병목과 연결하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "신고 목록 조회 쿼리의 개선안을 선택한 근거를 제시하지 않거나, 조회 시간 단축 수치 등 선택 근거와 다른 내용만 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "알림 중복 발송의 원인이었던 스케줄러 중복 실행을 배포 시 다시 방지할 수 있도록 구체적인 점검 항목으로 전환했는지 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 후 서버 두 대의 스케줄러가 동시에 실행되어 알림이 중복 발송되었다.",
          "task": "오류 수정 이후 같은 원인의 장애를 예방할 배포 체크리스트 항목을 정해야 했다.",
          "action": "배포 체크리스트에 실제로 추가한 스케줄러 확인 항목과 그 항목에서 점검하도록 정한 내용을 설명한다.",
          "result": "추가한 항목이 이후 배포 점검에 어떻게 활용되었는지는 답변 흐름을 이해하는 참고 정보로만 확인한다."
        },
        "expectedEvidence": [
          "알림 중복 발송의 재발 방지를 위해 배포 체크리스트에 추가한 실제 확인 항목",
          "해당 항목에서 점검하도록 정한 스케줄러의 대상이나 실행 상태",
          "서버 두 대의 스케줄러 중복 실행을 구별할 수 있도록 정한 확인 내용"
        ]
      },
      "question": "포켓마켓의 알림 중복 발송 오류 대응에서, 스케줄러 중복 실행의 재발 방지를 위해 배포 체크리스트에 넣었던 확인 항목은 무엇이었나요?",
      "answerTip": "당시 작성했던 내용을 떠올리며 차분하게 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "배포 체크리스트에 추가한 스케줄러 확인 항목을 밝히고, 두 서버의 중복 실행을 점검할 대상이나 확인할 실행 상태까지 구체적으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "배포 체크리스트에 스케줄러 정상 동작이나 중복 실행 여부를 확인하는 항목을 넣었다고 설명하지만, 실제로 무엇을 확인하도록 했는지는 일반적인 수준에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "배포 체크리스트에 추가한 스케줄러 확인 항목을 제시하지 않거나, 로그 추적이나 잠금 키 수정 내용만 설명한다."
          ]
        }
      }
    }
  ]
}
